output_text:
[
  {
    "id": "no_cart_in_single_file",
    "text": "Shopping carts are forbidden in single-file shelf aisles where the horizontal clearance is only one cell.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "enter_single_file_on_foot",
    "text": "An agent may enter a single-file shelf aisle only on foot, not while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "enterSingleFileAisle": {
          "pre": "MOVE",
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "enterSingleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_facing_shelf_interaction",
    "text": "Items located between facing shelves must not be interacted with while holding a cart.",
    "abstraction": {
      "state_properties": {
        "betweenFacingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "betweenFacingShelves",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "park_only_in_wide_cross_aisle",
    "text": "A cart may be parked or released only in a wide cross-aisle, not in a narrow shopping aisle.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "releaseCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "releaseCart",
          {
            "not": "wideCrossAisle"
          }
        ]
      }
    }
  },
  {
    "id": "parking_implies_pedestrian_aisle_visit",
    "text": "After parking a cart, the agent is obliged to enter a pedestrian-only single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "releaseCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "releaseCart",
      "discharge": "singleFileAisle"
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "Any cart that is parked must later be retrieved before the trajectory ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "releaseCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "recoverCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "releaseCart",
      "discharge": "recoverCart"
    }
  },
  {
    "id": "cartless_wide_moves_only_into_narrow",
    "text": "When cartless in a wide aisle, the agent may move only if the move enters a single-file pedestrian aisle.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "cartlessWideMoveAwayFromSingleFile": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "wideCrossAisle",
              "MOVE"
            ]
          },
          "post": {
            "not": "singleFileAisle"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessWideMoveAwayFromSingleFile"
    }
  },
  {
    "id": "cart_required_for_cart_accessible_shelves",
    "text": "Shelf interactions in cart-accessible aisles must be performed with the cart present.",
    "abstraction": {
      "state_properties": {
        "betweenFacingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "cartAccessibleShelf": {
          "and": [
            "adjShelf",
            {
              "not": "betweenFacingShelves"
            },
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "cartAccessibleShelf",
          "INTERACT"
        ]
      }
    }
  }
]
